mapper.sql:
AND (
    #{admin} = TRUE
    OR p.create_user = #{userId}
    OR JSON_CONTAINS(COALESCE(p.member, JSON_ARRAY()), JSON_QUOTE(CAST(#{userId} AS CHAR)))
)

LEFT JOIN automation_ui_execution scoped_latest ON scoped_latest.id = ( SELECT candidate.id FROM automation_ui_execution candidate WHERE candidate.scene_id = s.id
AND ( candidate.record_source = 'debug' OR ( candidate.record_source IS NULL AND (candidate.record_type IS NULL OR LOWER(TRIM(candidate.record_type)) NOT IN ('internal-interactive-context', 'interactive-execution-context')) AND candidate.test_plan_id IS NULL AND candidate.test_report_id IS NULL AND (candidate.trigger_type IS NULL OR LOWER(TRIM(candidate.trigger_type)) NOT IN ('test-plan', 'schedule')) ) )
AND ( candidate.record_source = 'test' OR ( candidate.record_source IS NULL AND (candidate.record_type IS NULL OR LOWER(TRIM(candidate.record_type)) NOT IN ('internal-interactive-context', 'interactive-execution-context')) AND ( candidate.test_plan_id IS NOT NULL OR candidate.test_report_id IS NOT NULL OR LOWER(TRIM(candidate.trigger_type)) IN ('test-plan', 'schedule') ) ) )
AND candidate.test_plan_id = #{executionScope.testPlanId}
AND candidate.test_report_id = #{executionScope.testReportId}
AND candidate.build_number = #{executionScope.buildNumber}
ORDER BY candidate.create_time DESC, candidate.id DESC LIMIT 1 )

mapper.select:
SELECT s.case_list
FROM automation_ui_scene s

WHERE s.id = #{sceneDbId}
  AND COALESCE(s.definition_version, 0) = #{definitionVersion}
  AND s.del_flag = 3

SELECT st.id, st.case_id, st.step_id, st.step_index, CAST(st.step_json AS CHAR) AS step_json,
       st.node_sha256
FROM automation_ui_scene_definition_step_read st

AND st.projection_id = rs.published_projection_id AND st.case_id = #{caseId}
ORDER BY st.step_index, st.id
LIMIT #{limit} OFFSET #{offset}
